<?php
namespace App\Http\Controllers;use App\Http\Requests\UpdateWatermarkSettingsRequest;use App\Jobs\ReprocessStudioWatermarks;use App\Services\Branding\WatermarkLogoStorage;use App\Services\Team\TeamAuthorization;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Inertia\Inertia;
class WatermarkSettingsController extends Controller{public function __construct(private TeamAuthorization$a){}private function owner(Request$r){$o=$this->a->ownerFor($r->user());abort_unless($o&&$this->a->allows($r->user(),$o,'manage_watermark'),403);return$o;}public function edit(Request$r){$o=$this->owner($r);$s=$o->watermarkSetting()->first();return Inertia::render('Settings/Watermark',['section'=>'watermark','settings'=>['size_percentage'=>$s?->size_percentage??15,'position'=>$s?->position??'bottom_right','has_logo'=>$s?->hasLogo()??false,'logo_url'=>$s?->hasLogo()?route('settings.watermark.logo'):null,'settings_version'=>$s?->settings_version??1]]);}public function update(UpdateWatermarkSettingsRequest$r,WatermarkLogoStorage$logos){$o=$this->owner($r);$s=$o->watermarkSetting()->first();$old=$s?->logo_object_key;$new=null;$data=$r->safe()->except(['logo','remove_logo']);try{if($r->hasFile('logo')){$stored=$logos->store($r->file('logo'),$o->id);$new=$stored['logo_object_key'];$data=array_merge($data,$stored);}elseif($r->boolean('remove_logo'))$data=array_merge($data,['logo_disk'=>null,'logo_object_key'=>null,'logo_mime_type'=>null,'logo_size_bytes'=>null,'logo_checksum'=>null]);$changed=!$s||collect($data)->contains(fn($v,$k)=>(string)$s->{$k}!==(string)$v);$version=$changed?(($s?->settings_version??0)+1):($s?->settings_version??1);$data['settings_version']=$version;DB::transaction(fn()=>$o->watermarkSetting()->updateOrCreate([],$data));}catch(\Illuminate\Validation\ValidationException$e){throw$e;}catch(\Throwable$e){if($new)try{$logos->delete($new);}catch(\Throwable){}report($e);return back()->withErrors(['logo'=>'We could not save the watermark logo. Please try again.'])->withInput();}if($old&&($new||$r->boolean('remove_logo')))try{$logos->delete($old);}catch(\Throwable$e){report($e);}if($changed)ReprocessStudioWatermarks::dispatch($o->id,$version);return back()->with('success',$changed?'Watermark settings saved. Gallery previews are being updated.':'Watermark settings updated successfully.');}}
